from collections import Counter


def minDeletionsBalanced(s, k):
    counts = list(Counter(s).values())
    best = len(s)
    for m in set(counts):
        cost = 0
        for c in counts:
            if c < m:
                cost += c
            elif c > m + k:
                cost += c - m - k
        best = min(best, cost)
    return best
